B64
  $SUDO chmod 755 "$FDIR"; $SUDO chmod 644 "$FDIR/server.mjs"
  if [ "$(sha256sum "$FDIR/server.mjs" | cut -d' ' -f1)" != "68dd2f894bb8c90eea59eb021ebc53282b6d3fef56773daed998edd0c93bdf30" ]; then
    echo "   File del lettore non integro: passo saltato."
  else
    started=0
    if [ "$FETCH_MODE" = auto ] || [ "$FETCH_MODE" = docker ]; then
      if command -v docker >/dev/null 2>&1; then
        echo "   Preparo il contenitore (la prima volta scarica l'immagine: può volerci qualche minuto)"
        $SUDO timeout 600 docker pull -q node:22-alpine >/dev/null 2>&1 || true
        # cartella dei connettori (chiavi): scrivibile solo dal servizio (utente «node», uid 1000), conservata negli aggiornamenti
        $SUDO mkdir -p "$FDATA"; $SUDO chown 1000:1000 "$FDATA" 2>/dev/null || true; $SUDO chmod 700 "$FDATA"
        # chiave dell'archivio clienti: creata una volta sola, mai sovrascritta, leggibile solo dal servizio
        $SUDO mkdir -p "$KDIR"; $SUDO chown 1000:1000 "$KDIR" 2>/dev/null || true; $SUDO chmod 700 "$KDIR"
        # la chiave si controlla e si scrive CON I PERMESSI GIUSTI (la cartella è chiusa) e non si sovrascrive MAI;
        # se c'è già, se ne tiene una copia datata accanto (una al giorno, mai sovrascritta)
        if $SUDO test -s "$KDIR/vault.key"; then
          $SUDO sh -c 'k="$1"; b="$1.bak-$(date +%Y%m%d)"; [ -e "$b" ] || cp -p "$k" "$b"' _ "$KDIR/vault.key"
        else
          $SUDO sh -c 'umask 077; set -C; head -c 32 /dev/urandom | od -An -tx1 | tr -d " \n" > "$1"' _ "$KDIR/vault.key" || true
          VAULT_NEWKEY=1
        fi
        $SUDO chown 1000:1000 "$KDIR/vault.key" 2>/dev/null || true; $SUDO chmod 600 "$KDIR/vault.key"
        echo "   Impronta della chiave dell'archivio: $($SUDO sha256sum "$KDIR/vault.key" | cut -c1-12) (deve restare uguale a ogni installazione)"

        # --- servizio Office (LibreOffice): legge i vecchi .doc e produce PDF identici agli originali ---
        OFFICE_ENV=""
        OMODE="${OFFICE_MODE:-auto}"
        MEMMB="${MEMMB_OVERRIDE:-$(awk '/MemTotal/ {print int($2/1024)}' /proc/meminfo 2>/dev/null || echo 0)}"
        if [ "$OMODE" = skip ]; then echo "   Servizio Office: saltato su richiesta."
        elif [ "${MEMMB:-0}" -lt 900 ] && [ "$OMODE" != force ]; then echo "   Servizio Office: saltato (servono almeno ~1 GB di RAM, qui ce ne sono ${MEMMB:-?} MB). I .doc vecchi useranno la copia semplificata."
        else
          ODIR="${ODIR:-/opt/giot-office}"
          $SUDO mkdir -p "$ODIR"
          base64 -d <<'OB64' | gunzip | $SUDO tee "$ODIR/office-server.py" >/dev/null
